const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // Define geometry for North Crimean Canal in Ukraine
  const canalGeometry = ee.Geometry.Polygon([[
    [33.8, 46.2], [34.2, 46.2], [34.2, 46.4], [33.8, 46.4], [33.8, 46.2]
  ]]);

  // Function to mask clouds in Sentinel-2
  function maskS2Clouds(image) {
    const qa = image.select('QA60');
    const cloudBitMask = 1 << 10;
    const cirrusBitMask = 1 << 11;
    const mask = qa.bitwiseAnd(cloudBitMask).eq(0)
                 .and(qa.bitwiseAnd(cirrusBitMask).eq(0));
    return image.updateMask(mask);
  }

  // Function to calculate NDWI and water extent
  function calculateWaterExtent(image) {
    const ndwi = image.normalizedDifference(['B3', 'B8']).rename('NDWI');
    const waterMask = ndwi.gt(0.0);
    return waterMask;
  }

  // Get June 3, 2023 data
  const juneCollection = ee.ImageCollection('COPERNICUS/S2_SR')
    .filterBounds(canalGeometry)
    .filterDate('2023-06-01', '2023-06-05')
    .map(maskS2Clouds)
    .map(calculateWaterExtent);

  // Get July 19, 2023 data  
  const julyCollection = ee.ImageCollection('COPERNICUS/S2_SR')
    .filterBounds(canalGeometry)
    .filterDate('2023-07-17', '2023-07-21')
    .map(maskS2Clouds)
    .map(calculateWaterExtent);

  // Check collection sizes
  const juneSize = juneCollection.size().getInfo();
  const julySize = julyCollection.size().getInfo();

  console.log(`June images: ${juneSize}, July images: ${julySize}`);

  if (juneSize === 0 || julySize === 0) {
    // Try Landsat as fallback
    const juneLandsat = ee.ImageCollection('LANDSAT/LC08/C02/T1_L2')
      .filterBounds(canalGeometry)
      .filterDate('2023-06-01', '2023-06-05');
    const julyLandsat = ee.ImageCollection('LANDSAT/LC08/C02/T1_L2')
      .filterBounds(canalGeometry)
      .filterDate('2023-07-17', '2023-07-21');

    const juneLandsatSize = juneLandsat.size().getInfo();
    const julyLandsatSize = julyLandsat.size().getInfo();

    console.log(`Landsat fallback - June: ${juneLandsatSize}, July: ${julyLandsatSize}`);

    if (juneLandsatSize === 0 || julyLandsatSize === 0) {
      console.log("<answer>C1</answer>");
      return;
    }
  }

  // Get median composites
  const juneWater = juneCollection.median();
  const julyWater = julyCollection.median();

  // Count water pixels
  const juneStats = juneWater.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: canalGeometry,
    scale: 100,
    maxPixels: 1e9
  }).getInfo();

  const julyStats = julyWater.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: canalGeometry,
    scale: 100,
    maxPixels: 1e9
  }).getInfo();

  const juneWaterPixels = juneStats.NDWI || 0;
  const julyWaterPixels = julyStats.NDWI || 0;

  console.log(`June water pixels: ${juneWaterPixels}`);
  console.log(`July water pixels: ${julyWaterPixels}`);

  // Check for valid pixels
  if (juneWaterPixels === 0 || julyWaterPixels === 0) {
    console.log("<answer>C2</answer>");
    return;
  }

  // Calculate percentage change
  const changePercent = ((julyWaterPixels - juneWaterPixels) / juneWaterPixels * 100);

  console.log(`Water change: ${changePercent.toFixed(1)}%`);

  // Validate result
  if (isNaN(changePercent) || !isFinite(changePercent)) {
    console.log("<answer>C3</answer>");
    return;
  }

  // Determine answer based on decrease
  if (changePercent < 0) {
    console.log("<answer>A</answer>");
  } else {
    console.log("<answer>B</answer>");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
